using System.Reflection;
using Microsoft.CodeAnalysis;

namespace Common;

internal static partial class Compatibility
{
    extension(IncrementalGeneratorPostInitializationContext context)
    {
        // TODO-NET8: Remove when we update to Roslyn 5.x
        public void AddEmbeddedAttributeDefinition()
        {
            context.AddSource("Microsoft.CodeAnalysis.EmbeddedAttribute",
            // lang=C#
            """
            // <auto-generated/>
            namespace Microsoft.CodeAnalysis
            {
                internal sealed partial class EmbeddedAttribute : global::System.Attribute
                {
                }
            }
            """);
        }
    }

    private static PropertyInfo? s_isUnion => field ??= typeof(ITypeSymbol).GetProperty("IsUnion");

    extension(ITypeSymbol symbol)
    {
        public bool IsUnion => (bool?)s_isUnion?.GetValue(symbol) ?? false;
    }
}
